<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf($_POST['csrf']??null)){http_response_code(419);exit('Invalid request.');}$id=(int)($_POST['id']??0);$s=$pdo->prepare('SELECT course_id,video_file,document_file FROM lessons WHERE id=?');$s->execute([$id]);$l=$s->fetch();if($l){foreach(['video_file','document_file'] as $f){if(!empty($l[$f])&&is_file(__DIR__.'/../uploads/'.$l[$f]))unlink(__DIR__.'/../uploads/'.$l[$f]);}$pdo->prepare('DELETE FROM lessons WHERE id=?')->execute([$id]);header('Location: course_edit.php?id='.$l['course_id']);exit;}header('Location: courses.php');